    name: np.zeros_like(W["target." + name])
    for name in ("w0", "b0", "w1", "b1", "w2", "b2",
                 "w3", "b3", "out", "bias")
}

# A conjunction is ReLU(sum of its literals - number_of_literals + 1).
for row, term in enumerate(terms):
    for col, bit in term.items():
        A["w0"][row, col] = 1 if bit else -1
    A["b0"][row] = 1 - sum(term.values())

